    61→
    62→type NetworkModules = {
    63→  opts: NetworkOptions;
    64→  privateKey: PrivateKey;
    65→  config: BeaconConfig;
    66→  logger: LoggerNode;
    67→  chain: IBeaconChain;
    68→  networkEventBus: NetworkEventBus;
    69→  aggregatorTracker: AggregatorTracker;
    70→  networkProcessor: NetworkProcessor;
