    72→};
    73→
    74→export type NetworkInitModules = {
    75→  opts: NetworkOptions;
    76→  config: BeaconConfig;
    77→  privateKey: PrivateKey;
    78→  peerStoreDir?: string;
    79→  logger: LoggerNode;
    80→  metrics: Metrics | null;
    81→  chain: IBeaconChain;
