    85→  gossipHandlers?: GossipHandlers;
    86→};
    87→
    88→/**
    89→ * Must support running both on worker and on main thread.
    90→ *
    91→ * Exists a front class that's what consumers interact with.
    92→ * This class will multiplex between:
    93→ * - libp2p in worker
    94→ * - libp2p in main thread
    95→ */
    96→export class Network implements INetwork {
    97→  readonly peerId: PeerId;
    98→  readonly custodyConfig: CustodyConfig;
    99→  // TODO: Make private
   100→  readonly events: INetworkEventBus;
   101→
   102→  private readonly logger: LoggerNode;
   103→  private readonly config: BeaconConfig;
   104→  private readonly clock: IClock;
   105→  private readonly chain: IBeaconChain;
   106→  // Used only for sleep() statements
   107→  private readonly controller: AbortController;
   108→
   109→  // TODO: Review
   110→  private readonly networkProcessor: NetworkProcessor;
   111→  private readonly core: INetworkCore;
   112→  private readonly aggregatorTracker: AggregatorTracker;
   113→
   114→  private subscribedToCoreTopics = false;
   115→  private connectedPeersSyncMeta = new Map<PeerIdStr, Omit<PeerSyncMeta, "peerId">>();
   116→
   117→  constructor(modules: NetworkModules) {
   118→    this.peerId = peerIdFromPrivateKey(modules.privateKey);
   119→    this.config = modules.config;
   120→    this.custodyConfig = modules.chain.custodyConfig;
   121→    this.logger = modules.logger;
   122→    this.chain = modules.chain;
   123→    this.clock = modules.chain.clock;
   124→    this.controller = new AbortController();
   125→    this.events = modules.networkEventBus;
   126→    this.networkProcessor = modules.networkProcessor;
   127→    this.core = modules.core;
   128→    this.aggregatorTracker = modules.aggregatorTracker;
   129→
   130→    this.events.on(NetworkEvent.peerConnected, this.onPeerConnected);
   131→    this.events.on(NetworkEvent.peerDisconnected, this.onPeerDisconnected);
   132→    this.chain.emitter.on(routes.events.EventType.head, this.onHead);
   133→    this.chain.emitter.on(routes.events.EventType.lightClientFinalityUpdate, ({data}) =>
   134→      this.onLightClientFinalityUpdate(data)
   135→    );
   136→    this.chain.emitter.on(routes.events.EventType.lightClientOptimisticUpdate, ({data}) =>
   137→      this.onLightClientOptimisticUpdate(data)
   138→    );
   139→    this.chain.emitter.on(ChainEvent.updateTargetCustodyGroupCount, this.onTargetGroupCountUpdated);
   140→    this.chain.emitter.on(ChainEvent.publishDataColumns, this.onPublishDataColumns);
   141→    this.chain.emitter.on(ChainEvent.updateStatus, this.onUpdateStatus);
   142→  }
   143→
   144→  static async init({
   145→    opts,
   146→    config,
   147→    logger,
   148→    metrics,
   149→    chain,
   150→    db,
   151→    gossipHandlers,
   152→    privateKey,
   153→    peerStoreDir,
   154→    getReqRespHandler,
   155→  }: NetworkInitModules): Promise<Network> {
   156→    const events = new NetworkEventBus();
   157→    const aggregatorTracker = new AggregatorTracker();
   158→
   159→    const activeValidatorCount = chain.getHeadState().epochCtx.currentShuffling.activeIndices.length;
   160→    const initialStatus = chain.getStatus();
   161→    const initialCustodyGroupCount = chain.custodyConfig.targetCustodyGroupCount;
   162→
   163→    if (opts.useWorker) {
   164→      logger.info("running libp2p instance in worker thread");
   165→    }
   166→
   167→    const core = opts.useWorker
   168→      ? await WorkerNetworkCore.init({
   169→          opts: {
   170→            ...opts,
   171→            peerStoreDir,
   172→            metricsEnabled: Boolean(metrics),
   173→            activeValidatorCount,
   174→            genesisTime: chain.genesisTime,
   175→            initialStatus,
   176→            initialCustodyGroupCount,
   177→          },
   178→          config,
   179→          privateKey,
   180→          logger,
   181→          events,
   182→          metrics,
   183→          getReqRespHandler,
   184→        })
   185→      : await NetworkCore.init({
   186→          opts,
   187→          config,
   188→          privateKey,
   189→          peerStoreDir,
   190→          logger,
   191→          clock: chain.clock,
   192→          events,
   193→          getReqRespHandler,
   194→          metricsRegistry: metrics ? new RegistryMetricCreator() : null,
   195→          initialStatus,
   196→          initialCustodyGroupCount,
   197→          activeValidatorCount,
   198→        });
   199→
   200→    const networkProcessor = new NetworkProcessor(
   201→      {chain, db, config, logger, metrics, events, gossipHandlers, core, aggregatorTracker},
   202→      opts
   203→    );
   204→
   205→    const multiaddresses = opts.localMultiaddrs?.join(",");
   206→    const peerId = peerIdFromPrivateKey(privateKey);
   207→    logger.info(`PeerId ${peerIdToString(peerId)}, Multiaddrs ${multiaddresses}`);
   208→
   209→    return new Network({
   210→      opts,
   211→      privateKey,
   212→      config,
   213→      logger,
   214→      chain,
   215→      networkEventBus: events,
   216→      aggregatorTracker,
