   221→
   222→  get closed(): boolean {
   223→    return this.controller.signal.aborted;
   224→  }
   225→
   226→  /** Destroy this instance. Can only be called once. */
   227→  async close(): Promise<void> {
   228→    if (this.closed) return;
   229→
   230→    this.events.off(NetworkEvent.peerConnected, this.onPeerConnected);
   231→    this.events.off(NetworkEvent.peerDisconnected, this.onPeerDisconnected);
   232→    this.chain.emitter.off(routes.events.EventType.head, this.onHead);
   233→    this.chain.emitter.off(routes.events.EventType.lightClientFinalityUpdate, this.onLightClientFinalityUpdate);
