   285→  }
   286→
   287→  getConnectedPeerSyncMeta(peerId: PeerIdStr): PeerSyncMeta {
   288→    const syncMeta = this.connectedPeersSyncMeta.get(peerId);
   289→    if (!syncMeta) {
   290→      throw new Error(`peerId=${prettyPrintPeerIdStr(peerId)} not in connectedPeerSyncMeta`);
   291→    }
   292→    return {peerId, ...syncMeta};
   293→  }
   294→
   295→  getConnectedPeerCount(): number {
   296→    return this.connectedPeersSyncMeta.size;
   297→  }
   298→
   299→  async getNetworkIdentity(): Promise<routes.node.NetworkIdentity> {
   300→    return this.core.getNetworkIdentity();
   301→  }
   302→
   303→  /**
   304→   * Subscribe to all gossip events. Safe to call multiple times
   305→   */
