   336→    const epoch = computeEpochAtSlot(signedBlock.message.slot);
   337→    const boundary = this.config.getForkBoundaryAtEpoch(epoch);
   338→
   339→    return this.publishGossip<GossipType.beacon_block>({type: GossipType.beacon_block, boundary}, signedBlock, {
   340→      ignoreDuplicatePublishError: true,
   341→    });
   342→  }
