   344→  async publishBlobSidecar(blobSidecar: deneb.BlobSidecar): Promise<number> {
   345→    const epoch = computeEpochAtSlot(blobSidecar.signedBlockHeader.message.slot);
   346→    const boundary = this.config.getForkBoundaryAtEpoch(epoch);
   347→
   348→    const subnet = blobSidecar.index;
   349→
   350→    return this.publishGossip<GossipType.blob_sidecar>({type: GossipType.blob_sidecar, boundary, subnet}, blobSidecar, {
