   363→      {
   364→        ignoreDuplicatePublishError: true,
   365→        // we ensure having all topic peers via prioritizePeers() function
   366→        // in the worse case, if there is 0 peer on the topic, the overall publish operation could be still a success
   367→        // because supernode will rebuild and publish missing data column sidecars for us
   368→        // hence we want to track sent peers as 0 instead of an error
