   405→  async publishBlsToExecutionChange(blsToExecutionChange: capella.SignedBLSToExecutionChange): Promise<number> {
   406→    const publishChanges = [];
   407→    for (const boundary of getActiveForkBoundaries(this.config, this.clock.currentEpoch)) {
   408→      const fork = ForkSeq[boundary.fork];
   409→
   410→      if (fork >= ForkSeq.capella) {
   411→        const publishPromise = this.publishGossip<GossipType.bls_to_execution_change>(
   412→          {type: GossipType.bls_to_execution_change, boundary},
   413→          blsToExecutionChange,
   414→          {ignoreDuplicatePublishError: true}
   415→        );
   416→        publishChanges.push(publishPromise);
   417→      }
   418→    }
   419→
   420→    if (publishChanges.length === 0) {
   421→      throw Error("No capella+ fork active yet to publish blsToExecutionChange");
   422→    }
   423→    return Promise.any(publishChanges);
   424→  }
