   490→  private async publishGossip<K extends GossipType>(
   491→    topic: GossipTopicMap[K],
   492→    object: GossipTypeMap[K],
   493→    opts?: PublishOpts | undefined
   494→  ): Promise<number> {
   495→    const topicStr = stringifyGossipTopic(this.config, topic);
   496→    const sszType = getGossipSSZType(topic);
   497→    const messageData = (sszType.serialize as (object: GossipTypeMap[GossipType]) => Uint8Array)(object);
   498→    opts = {
   499→      ...opts,
   500→      ignoreDuplicatePublishError: gossipTopicIgnoreDuplicatePublishError[topic.type],
   501→    };
   502→    const sentPeers = await this.core.publishGossip(topicStr, messageData, opts);
   503→
   504→    this.logger.verbose("Publish to topic", {topic: topicStr, sentPeers, currentSlot: this.clock.currentSlot});
   505→    return sentPeers;
   506→  }
