   687→  private onLightClientFinalityUpdate = async (finalityUpdate: LightClientFinalityUpdate): Promise<void> => {
   688→    // TODO: Review is OK to remove if (this.hasAttachedSyncCommitteeMember())
   689→
   690→    try {
   691→      // messages SHOULD be broadcast after one-third of slot has transpired
   692→      // https://github.com/ethereum/consensus-specs/blob/dev/specs/altair/light-client/p2p-interface.md#sync-committee
   693→      await this.waitOneThirdOfSlot(finalityUpdate.signatureSlot);
   694→      await this.publishLightClientFinalityUpdate(finalityUpdate);
   695→    } catch (e) {
   696→      // Non-mandatory route on most of network as of Oct 2022. May not have found any peers on topic yet
   697→      // Remove once https://github.com/ChainSafe/js-libp2p-gossipsub/issues/367
   698→      if (!isPublishToZeroPeersError(e as Error)) {
   699→        this.logger.debug("Error on BeaconGossipHandler.onLightclientFinalityUpdate", {}, e as Error);
   700→      }
   701→    }
   702→  };
   703→
   704→  private onLightClientOptimisticUpdate = async (optimisticUpdate: LightClientOptimisticUpdate): Promise<void> => {
   705→    // TODO: Review is OK to remove if (this.hasAttachedSyncCommitteeMember())
   706→
   707→    try {
   708→      // messages SHOULD be broadcast after one-third of slot has transpired
   709→      // https://github.com/ethereum/consensus-specs/blob/dev/specs/altair/light-client/p2p-interface.md#sync-committee
   710→      await this.waitOneThirdOfSlot(optimisticUpdate.signatureSlot);
   711→      await this.publishLightClientOptimisticUpdate(optimisticUpdate);
   712→    } catch (e) {
   713→      // Non-mandatory route on most of network as of Oct 2022. May not have found any peers on topic yet
   714→      // Remove once https://github.com/ChainSafe/js-libp2p-gossipsub/issues/367
   715→      if (!isPublishToZeroPeersError(e as Error)) {
   716→        this.logger.debug("Error on BeaconGossipHandler.onLightclientOptimisticUpdate", {}, e as Error);
   717→      }
   718→    }
   719→  };
