   721→  private waitOneThirdOfSlot = async (slot: number): Promise<void> => {
   722→    const secAtSlot = computeTimeAtSlot(this.config, slot + 1 / 3, this.chain.genesisTime);
   723→    const msToSlot = secAtSlot * 1000 - Date.now();
   724→    await sleep(msToSlot, this.controller.signal);
   725→  };
