    76→ * - In the main thread
    77→ *
    78→ * libp2p holds the reference to the TCP transport socket. libp2p is in a worker, what components
    79→ * must be in a worker too?
    80→ * - MetadataController: Read by ReqRespBeaconNode, written by AttnetsService + SyncnetsService
    81→ * - PeerRpcScoreStore
    82→ * - ReqRespBeaconNode: Must be in worker, depends on libp2p
    83→ * - Eth2Gossipsub: Must be in worker, depends on libp2p
    84→ * - AttnetsService
    85→ * - SyncnetsService
    86→ * - PeerManager
    87→ * - NetworkProcessor: Must be in the main thread, depends on chain
    88→ */
    89→export class NetworkCore implements INetworkCore {
    90→  // Internal modules
    91→  private readonly libp2p: Libp2p;
    92→  private readonly attnetsService: IAttnetsService;
    93→  private readonly syncnetsService: SyncnetsService;
    94→  private readonly peerManager: PeerManager;
    95→  private readonly networkConfig: NetworkConfig;
    96→  private readonly peersData: PeersData;
    97→  private readonly reqResp: ReqRespBeaconNode;
    98→  private readonly gossip: Eth2Gossipsub;
    99→  // TODO: Review if here is best place, and best architecture
   100→  private readonly metadata: MetadataController;
   101→  private readonly logger: LoggerNode;
   102→  private readonly config: BeaconConfig;
   103→  private readonly clock: IClock;
   104→  private readonly statusCache: LocalStatusCache;
   105→  private readonly metrics: NetworkCoreMetrics | null;
   106→  private readonly opts: NetworkOptions;
   107→
   108→  // Internal state
   109→  private readonly forkBoundariesByEpoch = new Map<Epoch, ForkBoundary>();
   110→  private closed = false;
   111→
   112→  constructor(modules: Mods) {
   113→    this.libp2p = modules.libp2p;
   114→    this.gossip = modules.gossip;
   115→    this.reqResp = modules.reqResp;
   116→    this.attnetsService = modules.attnetsService;
   117→    this.syncnetsService = modules.syncnetsService;
   118→    this.peerManager = modules.peerManager;
   119→    this.networkConfig = modules.networkConfig;
   120→    this.peersData = modules.peersData;
   121→    this.metadata = modules.metadata;
   122→    this.logger = modules.logger;
   123→    this.config = modules.config;
   124→    this.clock = modules.clock;
   125→    this.statusCache = modules.statusCache;
   126→    this.metrics = modules.metrics;
   127→    this.opts = modules.opts;
   128→
   129→    this.clock.on(ClockEvent.epoch, this.onEpoch);
   130→  }
   131→
   132→  static async init({
   133→    opts,
   134→    config,
   135→    privateKey,
   136→    peerStoreDir,
   137→    logger,
   138→    metricsRegistry,
   139→    events,
   140→    clock,
   141→    getReqRespHandler,
   142→    activeValidatorCount,
   143→    initialStatus,
   144→    initialCustodyGroupCount,
   145→  }: BaseNetworkInit): Promise<NetworkCore> {
   146→    const libp2p = await createNodeJsLibp2p(privateKey, opts, {
   147→      peerStoreDir,
   148→      metrics: Boolean(metricsRegistry),
   149→      metricsRegistry: metricsRegistry ?? undefined,
   150→    });
   151→
   152→    const metrics = metricsRegistry ? createNetworkCoreMetrics(metricsRegistry) : null;
   153→    const peersData = new PeersData();
   154→    const peerRpcScores = new PeerRpcScoreStore(opts, metrics, logger);
   155→    const statusCache = new LocalStatusCache(initialStatus);
   156→
   157→    // Bind discv5's ENR to local metadata
   158→    // resolve circular dependency by setting `discv5` variable after the peer manager is instantiated
   159→    let discv5: Discv5Worker | undefined;
   160→    const onMetadataSetValue = function onMetadataSetValue(key: string, value: Uint8Array): void {
   161→      discv5?.setEnrValue(key, value).catch((e) => logger.error("error on setEnrValue", {key}, e));
   162→    };
   163→    const peerId = peerIdFromPrivateKey(privateKey);
   164→    const nodeId = computeNodeId(peerId);
   165→    const networkConfig: NetworkConfig = {
   166→      nodeId,
   167→      config,
   168→      custodyConfig: new CustodyConfig({nodeId, config, initialCustodyGroupCount}),
   169→    };
   170→    const metadata = new MetadataController({}, {networkConfig, logger, onSetValue: onMetadataSetValue});
   171→
   172→    const reqResp = new ReqRespBeaconNode(
   173→      {
   174→        config,
   175→        libp2p,
   176→        metadata,
   177→        peerRpcScores,
   178→        logger,
   179→        events,
   180→        metrics,
   181→        peersData,
   182→        statusCache,
   183→        getHandler: getReqRespHandler,
   184→      },
   185→      opts
   186→    );
   187→
   188→    const gossip = new Eth2Gossipsub(opts, {
   189→      networkConfig,
   190→      libp2p,
   191→      logger,
   192→      metricsRegister: metricsRegistry,
   193→      eth2Context: {
   194→        activeValidatorCount,
   195→        currentSlot: clock.currentSlot,
   196→        currentEpoch: clock.currentEpoch,
   197→      },
   198→      peersData,
   199→      events,
   200→    });
   201→
   202→    // Note: should not be necessary, already called in createNodeJsLibp2p()
   203→    await libp2p.start();
   204→
   205→    await reqResp.start();
   206→    // should be called before AttnetsService constructor so that node subscribe to deterministic attnet topics
   207→    await gossip.start();
   208→
   209→    const attnetsService = new AttnetsService(
   210→      config,
   211→      clock,
   212→      gossip,
   213→      metadata,
   214→      logger,
   215→      metrics,
   216→      networkConfig.nodeId,
   217→      opts
   218→    );
   219→    const syncnetsService = new SyncnetsService(config, clock, gossip, metadata, logger, metrics, opts);
   220→
   221→    const peerManager = await PeerManager.init(
   222→      {
   223→        privateKey,
   224→        libp2p,
   225→        gossip,
   226→        reqResp,
   227→        attnetsService,
   228→        syncnetsService,
   229→        logger,
   230→        metrics,
   231→        clock,
   232→        peerRpcScores,
   233→        events,
   234→        networkConfig,
   235→        peersData,
   236→        statusCache,
   237→      },
   238→      opts
   239→    );
   240→
   241→    // Network spec decides version changes based on clock epoch, not head epoch
   242→    const boundary = config.getForkBoundaryAtEpoch(clock.currentEpoch);
   243→
   244→    // Register only ReqResp protocols relevant to clock's epoch
   245→    reqResp.registerProtocolsAtBoundary(boundary);
   246→
   247→    // Bind discv5's ENR to local metadata
   248→    // biome-ignore lint/complexity/useLiteralKeys: `discovery` is a private attribute
   249→    discv5 = peerManager["discovery"]?.discv5;
   250→
   251→    // Initialize ENR with clock's fork
   252→    metadata.upstreamValues(clock.currentEpoch);
   253→
   254→    return new NetworkCore({
   255→      libp2p,
   256→      reqResp,
   257→      gossip,
   258→      attnetsService,
   259→      syncnetsService,
   260→      peerManager,
   261→      networkConfig,
   262→      peersData,
   263→      metadata,
   264→      logger,
   265→      config,
   266→      clock,
   267→      statusCache,
   268→      metrics,
   269→      opts,
   270→    });
   271→  }
   272→
   273→  /** Destroy this instance. Can only be called once. */
   274→  async close(): Promise<void> {
   275→    if (this.closed) return;
   276→
   277→    this.clock.off(ClockEvent.epoch, this.onEpoch);
   278→
   279→    // Must goodbye and disconnect before stopping libp2p
   280→    await this.peerManager.goodbyeAndDisconnectAllPeers();
   281→    this.logger.debug("network sent goodbye to all peers");
   282→    await this.peerManager.close();
   283→    this.logger.debug("network peerManager closed");
   284→    await this.gossip.stop();
   285→    this.logger.debug("network gossip closed");
   286→    await this.reqResp.stop();
   287→    await this.reqResp.unregisterAllProtocols();
   288→    this.logger.debug("network reqResp closed");
   289→    this.attnetsService.close();
   290→    this.syncnetsService.close();
   291→    await this.libp2p.stop();
   292→    this.logger.debug("network lib2p closed");
   293→
   294→    this.closed = true;
   295→  }
   296→
   297→  getNetworkConfig(): NetworkConfig {
   298→    return this.networkConfig;
   299→  }
   300→
   301→  async scrapeMetrics(): Promise<string> {
   302→    return [
   303→      (await this.metrics?.register.metrics()) ?? "",
   304→      // biome-ignore lint/complexity/useLiteralKeys: `discovery` is a private attribute
   305→      (await this.peerManager["discovery"]?.discv5.scrapeMetrics()) ?? "",
   306→    ]
   307→      .filter((str) => str.length > 0)
   308→      .join("\n\n");
   309→  }
   310→
   311→  async updateStatus(status: Status): Promise<void> {
   312→    this.statusCache.update(status);
   313→  }
   314→
   315→  async reportPeer(peer: PeerIdStr, action: PeerAction, actionName: string): Promise<void> {
   316→    this.peerManager.reportPeer(peerIdFromString(peer), action, actionName);
   317→  }
   318→
   319→  async reStatusPeers(peers: PeerIdStr[]): Promise<void> {
   320→    this.peerManager.reStatusPeers(peers);
   321→  }
   322→
   323→  /**
   324→   * Request att subnets up `toSlot`. Network will ensure to mantain some peers for each
   325→   */
   326→  async prepareBeaconCommitteeSubnets(subscriptions: CommitteeSubscription[]): Promise<void> {
   327→    this.attnetsService.addCommitteeSubscriptions(subscriptions);
   328→    if (subscriptions.length > 0) this.peerManager.onCommitteeSubscriptions();
   329→  }
   330→
   331→  async prepareSyncCommitteeSubnets(subscriptions: CommitteeSubscription[]): Promise<void> {
   332→    this.syncnetsService.addCommitteeSubscriptions(subscriptions);
   333→    if (subscriptions.length > 0) this.peerManager.onCommitteeSubscriptions();
   334→  }
   335→
   336→  /**
   337→   * Subscribe to all gossip events. Safe to call multiple times
   338→   */
   339→  async subscribeGossipCoreTopics(): Promise<void> {
   340→    if (!(await this.isSubscribedToGossipCoreTopics())) {
   341→      this.logger.info("Subscribed gossip core topics");
   342→    }
   343→
   344→    for (const boundary of getActiveForkBoundaries(this.config, this.clock.currentEpoch)) {
   345→      this.subscribeCoreTopicsAtBoundary(this.networkConfig, boundary);
   346→    }
   347→  }
   348→
   349→  /**
   350→   * Unsubscribe from all gossip events. Safe to call multiple times
   351→   */
   352→  async unsubscribeGossipCoreTopics(): Promise<void> {
   353→    for (const boundary of this.forkBoundariesByEpoch.values()) {
   354→      this.unsubscribeCoreTopicsAtBoundary(this.networkConfig, boundary);
   355→    }
   356→  }
   357→
   358→  async isSubscribedToGossipCoreTopics(): Promise<boolean> {
   359→    return this.forkBoundariesByEpoch.size > 0;
   360→  }
   361→
   362→  sendReqRespRequest(data: OutgoingRequestArgs): AsyncIterable<ResponseIncoming> {
   363→    const peerId = peerIdFromString(data.peerId);
   364→    return this.reqResp.sendRequestWithoutEncoding(peerId, data.method, data.versions, data.requestData);
   365→  }
   366→
   367→  async publishGossip(topic: string, data: Uint8Array, opts?: PublishOpts | undefined): Promise<number> {
   368→    const {recipients} = await this.gossip.publish(topic, data, opts);
   369→    return recipients.length;
   370→  }
   371→
   372→  /**
   373→   * Handler of ChainEvent.updateTargetCustodyGroupCount event
   374→   * Updates the target custody group count in the network config and metadata.
   375→   * Also subscribes to new data_column_sidecar subnet topics for the new custody group count.
   376→   */
   377→  async setTargetGroupCount(count: number): Promise<void> {
   378→    this.networkConfig.custodyConfig.updateTargetCustodyGroupCount(count);
   379→    this.metadata.custodyGroupCount = count;
   380→    // cannot call subscribeGossipCoreTopics() because we subsribed to core topics already
   381→    // we only need to subscribe to more data_column_sidecar topics
   382→    const dataColumnSubnetTopics = getDataColumnSidecarTopics(this.networkConfig);
   383→    const activeBoundaries = getActiveForkBoundaries(this.config, this.clock.currentEpoch);
   384→    for (const boundary of activeBoundaries) {
   385→      for (const topic of dataColumnSubnetTopics) {
   386→        // there are existing subscriptions for old subnets, in that case gossipsub will just ignore
   387→        this.gossip.subscribeTopic({...topic, boundary});
   388→      }
   389→    }
   390→  }
   391→
   392→  // REST API queries
   393→
   394→  async getNetworkIdentity(): Promise<routes.node.NetworkIdentity> {
   395→    // biome-ignore lint/complexity/useLiteralKeys: `discovery` is a private attribute
   396→    const enr = await this.peerManager["discovery"]?.discv5.enr();
   397→
   398→    // enr.getFullMultiaddr can counterintuitively return undefined near startup if the enr.ip or enr.ip6 is not set.
   399→    // Eventually, the enr will be updated with the correct ip after discv5 runs for a while.
   400→
   401→    // Node's addresses on which is listening for discv5 requests.
   402→    // The example provided by the beacon-APIs show a _full_ multiaddr, ie including the peer id, so we include it.
   403→    const discoveryAddresses = [
   404→      (await enr?.getFullMultiaddr("udp"))?.toString(),
   405→      (await enr?.getFullMultiaddr("udp6"))?.toString(),
   406→    ].filter((addr): addr is string => Boolean(addr));
   407→
   408→    // Node's addresses on which eth2 RPC requests are served.
   409→    const p2pAddresses = [
   410→      // It is useful to include listen multiaddrs even if they likely aren't public IPs
   411→      // This means that we will always return some multiaddrs
   412→      ...this.libp2p.getMultiaddrs().map((ma) => ma.toString()),
   413→
   414→      (await enr?.getFullMultiaddr("tcp"))?.toString(),
   415→      (await enr?.getFullMultiaddr("tcp6"))?.toString(),
   416→      (await enr?.getFullMultiaddr("quic"))?.toString(),
   417→      (await enr?.getFullMultiaddr("quic6"))?.toString(),
   418→    ].filter((addr): addr is string => Boolean(addr));
   419→
   420→    return {
   421→      peerId: peerIdToString(this.libp2p.peerId),
   422→      enr: enr?.encodeTxt() || "",
   423→      discoveryAddresses,
   424→      p2pAddresses,
   425→      metadata: this.metadata.json,
   426→    };
   427→  }
   428→
   429→  getConnectionsByPeer(): Map<string, Connection[]> {
   430→    const m = new Map<string, Connection[]>();
   431→    for (const [k, v] of getConnectionsMap(this.libp2p).entries()) {
   432→      m.set(k, v.value);
   433→    }
   434→    return m;
   435→  }
   436→
   437→  async getConnectedPeers(): Promise<PeerIdStr[]> {
   438→    return this.peerManager.getConnectedPeerIds().map(peerIdToString);
   439→  }
   440→
   441→  async getConnectedPeerCount(): Promise<number> {
   442→    return this.peerManager.getConnectedPeerIds().length;
   443→  }
   444→
   445→  // Debug
   446→
   447→  async connectToPeer(peerIdStr: PeerIdStr, multiaddrStrArr: MultiaddrStr[]): Promise<void> {
   448→    const peer = peerIdFromString(peerIdStr);
   449→    await this.libp2p.peerStore.merge(peer, {multiaddrs: multiaddrStrArr.map(multiaddr)});
   450→    await this.libp2p.dial(peer);
   451→  }
   452→
   453→  async disconnectPeer(peerIdStr: PeerIdStr): Promise<void> {
   454→    await this.libp2p.hangUp(peerIdFromString(peerIdStr));
   455→  }
   456→
   457→  private _dumpPeer(peerIdStr: string, connections: Connection[]): routes.lodestar.LodestarNodePeer {
   458→    const peerData = this.peersData.connectedPeers.get(peerIdStr);
   459→    const fork = this.config.getForkName(this.clock.currentSlot);
   460→    if (isForkPostFulu(fork) && peerData?.status) {
   461→      (peerData.status as fulu.Status).earliestAvailableSlot =
   462→        (peerData.status as fulu.Status).earliestAvailableSlot ?? 0;
   463→    }
   464→    return {
   465→      ...formatNodePeer(peerIdStr, connections),
   466→      agentVersion: peerData?.agentVersion ?? "NA",
   467→      status: peerData?.status ? sszTypesFor(fork).Status.toJson(peerData.status) : null,
   468→      metadata: peerData?.metadata ? sszTypesFor(fork).Metadata.toJson(peerData.metadata) : null,
   469→      agentClient: String(peerData?.agentClient ?? "Unknown"),
   470→      lastReceivedMsgUnixTsMs: peerData?.lastReceivedMsgUnixTsMs ?? 0,
   471→      lastStatusUnixTsMs: peerData?.lastStatusUnixTsMs ?? 0,
   472→      connectedUnixTsMs: peerData?.connectedUnixTsMs ?? 0,
   473→    };
   474→  }
   475→
   476→  async dumpPeer(peerIdStr: string): Promise<routes.lodestar.LodestarNodePeer | undefined> {
   477→    const connections = this.getConnectionsByPeer().get(peerIdStr);
   478→    return connections ? this._dumpPeer(peerIdStr, connections) : undefined;
   479→  }
   480→
   481→  async dumpPeers(): Promise<routes.lodestar.LodestarNodePeer[]> {
   482→    return Array.from(this.getConnectionsByPeer().entries()).map(([peerIdStr, connections]) =>
   483→      this._dumpPeer(peerIdStr, connections)
   484→    );
   485→  }
   486→
   487→  async dumpPeerScoreStats(): Promise<PeerScoreStats> {
   488→    return this.peerManager.dumpPeerScoreStats();
   489→  }
   490→
   491→  async dumpGossipPeerScoreStats(): Promise<PeerScoreStatsDump> {
   492→    return this.gossip.dumpPeerScoreStats();
   493→  }
   494→
   495→  async dumpDiscv5KadValues(): Promise<string[]> {
   496→    // biome-ignore lint/complexity/useLiteralKeys: `discovery` is a private attribute
   497→    return (await this.peerManager["discovery"]?.discv5?.kadValues())?.map((enr) => enr.encodeTxt()) ?? [];
   498→  }
   499→
   500→  async dumpMeshPeers(): Promise<Record<string, string[]>> {
   501→    const meshPeers: Record<string, string[]> = {};
   502→    for (const topic of this.gossip.getTopics()) {
   503→      meshPeers[topic] = this.gossip.getMeshPeers(topic);
   504→    }
   505→    return meshPeers;
   506→  }
   507→
   508→  async writeNetworkThreadProfile(): Promise<string> {
   509→    throw new Error("Method not implemented, please configure network thread");
   510→  }
   511→
   512→  async writeDiscv5Profile(durationMs: number, dirpath: string): Promise<string> {
   513→    // biome-ignore lint/complexity/useLiteralKeys: `discovery` is a private attribute
   514→    return this.peerManager["discovery"]?.discv5.writeProfile(durationMs, dirpath) ?? "no discv5";
   515→  }
   516→
   517→  writeNetworkHeapSnapshot(): Promise<string> {
   518→    throw new Error("Method not implemented, please configure network thread");
   519→  }
   520→
   521→  writeDiscv5HeapSnapshot(prefix: string, dirpath: string): Promise<string> {
   522→    // biome-ignore lint/complexity/useLiteralKeys: `discovery` is a private attribute
   523→    return this.peerManager["discovery"]?.discv5.writeHeapSnapshot(prefix, dirpath) ?? Promise.resolve("no discv5");
   524→  }
   525→
   526→  /**
   527→   * Handle subscriptions through fork boundary transitions, @see FORK_EPOCH_LOOKAHEAD
   528→   */
   529→  private onEpoch = async (epoch: Epoch): Promise<void> => {
   530→    try {
   531→      // Compute prev and next fork boundary shifted, so next boundary is still next at forkEpoch + FORK_EPOCH_LOOKAHEAD
   532→      const activeBoundaries = getActiveForkBoundaries(this.config, epoch);
   533→      for (let i = 0; i < activeBoundaries.length; i++) {
   534→        // Only when a new fork boundary is scheduled post this one
   535→        if (activeBoundaries[i + 1] !== undefined) {
   536→          const prevBoundary = activeBoundaries[i];
   537→          const nextBoundary = activeBoundaries[i + 1];
   538→          const nextBoundaryEpoch = nextBoundary.epoch;
   539→
   540→          // Before fork boundary transition
   541→          if (epoch === nextBoundaryEpoch - FORK_EPOCH_LOOKAHEAD) {
   542→            // Don't subscribe to new fork boundary if the node is not subscribed to any topic
   543→            if (await this.isSubscribedToGossipCoreTopics()) {
   544→              this.subscribeCoreTopicsAtBoundary(this.networkConfig, nextBoundary);
   545→              this.logger.info("Subscribing gossip topics for next fork boundary", nextBoundary);
   546→            } else {
   547→              this.logger.info("Skipping subscribing gossip topics for next fork boundary", nextBoundary);
   548→            }
   549→            this.attnetsService.subscribeSubnetsNextBoundary(nextBoundary);
   550→            this.syncnetsService.subscribeSubnetsNextBoundary(nextBoundary);
   551→          }
   552→
   553→          // On fork boundary transition
   554→          if (epoch === nextBoundaryEpoch) {
   555→            // updateEth2Field() MUST be called with clock epoch, onEpoch event is emitted in response to clock events
   556→            this.metadata.updateEth2Field(epoch);
   557→            this.reqResp.registerProtocolsAtBoundary(nextBoundary);
   558→          }
   559→
   560→          // After fork boundary transition
   561→          if (epoch === nextBoundaryEpoch + FORK_EPOCH_LOOKAHEAD) {
   562→            this.logger.info("Unsubscribing gossip topics of previous fork boundary", prevBoundary);
   563→            this.unsubscribeCoreTopicsAtBoundary(this.networkConfig, prevBoundary);
   564→            this.attnetsService.unsubscribeSubnetsPrevBoundary(prevBoundary);
   565→            this.syncnetsService.unsubscribeSubnetsPrevBoundary(prevBoundary);
   566→          }
   567→        }
   568→      }
   569→    } catch (e) {
   570→      this.logger.error("Error on BeaconGossipHandler.onEpoch", {epoch}, e as Error);
   571→    }
   572→  };
   573→
   574→  private subscribeCoreTopicsAtBoundary(networkConfig: NetworkConfig, boundary: ForkBoundary): void {
   575→    if (this.forkBoundariesByEpoch.has(boundary.epoch)) return;
   576→    this.forkBoundariesByEpoch.set(boundary.epoch, boundary);
   577→    const {subscribeAllSubnets, disableLightClientServer} = this.opts;
   578→
   579→    for (const topic of getCoreTopicsAtFork(networkConfig, boundary.fork, {
   580→      subscribeAllSubnets,
   581→      disableLightClientServer,
   582→    })) {
   583→      this.gossip.subscribeTopic({...topic, boundary});
   584→    }
   585→  }
   586→
   587→  private unsubscribeCoreTopicsAtBoundary(networkConfig: NetworkConfig, boundary: ForkBoundary): void {
   588→    if (!this.forkBoundariesByEpoch.has(boundary.epoch)) return;
   589→    this.forkBoundariesByEpoch.delete(boundary.epoch);
   590→    const {subscribeAllSubnets, disableLightClientServer} = this.opts;
   591→
   592→    for (const topic of getCoreTopicsAtFork(networkConfig, boundary.fork, {
   593→      subscribeAllSubnets,
   594→      disableLightClientServer,
   595→    })) {
   596→      this.gossip.unsubscribeTopic({...topic, boundary});
   597→    }
   598→  }
   599→}
